"""Add `= None` defaults to pydantic fields annotated as Optional[...] without an explicit default.

pydantic v1 treated `x: Optional[T]` as not required with default None; v2 makes it required.
"""
import ast
import sys
from pathlib import Path

MODEL_DIR = Path("cortex_xdr_client")

TARGETS = sorted(MODEL_DIR.rglob("*.py"))


def has_none(annotation):
    if isinstance(annotation, ast.Subscript):
        value = annotation.value
        name = getattr(value, "id", None)
        if name == "Optional":
            return True
        if name == "Union":
            sl = annotation.slice
            elts = sl.elts if isinstance(sl, ast.Tuple) else [sl]
            return any(isinstance(e, ast.Constant) and e.value is None for e in elts)
        return has_none(value) or has_none(annotation.slice)
    if isinstance(annotation, ast.BinOp):
        return has_none(annotation.left) or has_none(annotation.right)
    if isinstance(annotation, ast.Tuple):
        return any(has_none(e) for e in annotation.elts)
    return False


def main(apply):
    for path in TARGETS:
        text = path.read_text(encoding="utf-8")
        lines = text.splitlines(keepends=True)
        tree = ast.parse(text)
        edits = []
        for node in ast.walk(tree):
            if not isinstance(node, ast.ClassDef):
                continue
            for stmt in node.body:
                if isinstance(stmt, ast.AnnAssign) and stmt.value is None and has_none(stmt.annotation):
                    if stmt.end_lineno != stmt.lineno:
                        print(f"SKIP multi-line {path}:{stmt.lineno}")
                        continue
                    line = lines[stmt.lineno - 1]
                    if "#" in line:
                        print(f"SKIP comment {path}:{stmt.lineno}: {line.rstrip()}")
                        continue
                    edits.append(stmt.lineno - 1)
        if not edits:
            continue
        for idx in sorted(edits, reverse=True):
            line = lines[idx]
            stripped = line.rstrip("\r\n")
            newline = line[len(stripped):]
            lines[idx] = stripped + " = None" + newline
        print(f"{path}: {len(edits)} fields")
        if apply:
            path.write_text("".join(lines), encoding="utf-8")


if __name__ == "__main__":
    main(apply="--apply" in sys.argv)

